      && verifier.VerifyField(tablePos, 34 /*DRY_MASS_KG*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 36 /*INITIAL_MASS_KG*/, 8 /*double*/, 8, false)
      && verifier.VerifyString(tablePos, 38 /*EPHEMERIS_SOURCE*/, false)
      && verifier.VerifyString(tablePos, 40 /*COMMENT*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
